class Solution {
public:
    vector<int> parent;
    vector<int> rnk;

    int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    void unite(int x, int y) {
        int rx = find(x), ry = find(y);
        if (rx == ry) return;
        if (rnk[rx] < rnk[ry]) swap(rx, ry);
        parent[ry] = rx;
        if (rnk[rx] == rnk[ry]) rnk[rx]++;
    }

    vector<int> findAllPeople(int n, vector<vector<int>>& meetings, int firstPerson) {
        parent.resize(n);
        rnk.assign(n, 0);
        for (int i = 0; i < n; i++) parent[i] = i;

        vector<bool> knows(n, false);
        knows[0] = true;
        knows[firstPerson] = true;

        sort(meetings.begin(), meetings.end(),
             [](const vector<int>& a, const vector<int>& b) { return a[2] < b[2]; });

        int m = meetings.size();
        int i = 0;
        while (i < m) {
            int j = i;
            while (j < m && meetings[j][2] == meetings[i][2]) j++;

            unordered_set<int> involved;
            for (int k = i; k < j; k++) {
                unite(meetings[k][0], meetings[k][1]);
                involved.insert(meetings[k][0]);
                involved.insert(meetings[k][1]);
            }

            unordered_set<int> knownRoots;
            for (int p : involved) {
                if (knows[p]) knownRoots.insert(find(p));
            }
            for (int p : involved) {
                if (knownRoots.count(find(p))) knows[p] = true;
            }

            for (int p : involved) {
                parent[p] = p;
                rnk[p] = 0;
            }

            i = j;
        }

        vector<int> ans;
        for (int k = 0; k < n; k++) {
            if (knows[k]) ans.push_back(k);
        }
        return ans;
    }
};
